	sections = {
		{
			title = "Summary",
			text = [=[Keeper Albagorm is the {link:night-elves}kaldorei{/link} guardian of {link:stonetalon-peak}Stonetalon Peak{/link}. He calls himself a protector of the forest spirits, and from the summit he has watched the forests below fall to fire and saw. He has not wept. He has planned. His answer to the ruin of the {link:the-charred-vale}Charred Vale{/link} is not vengeance alone but regrowth, and he means to see the vale green again.]=],
		},
		{
			title = "Significance",
			text = [=[Albagorm is the voice of the old {link:night-elves}kaldorei{/link} faith in {link:stonetalon-mountains}Stonetalon{/link}. He sees the land as a single living thing, and the goblins and harpies as wounds upon it. He also knows that the druids of the peak cannot heal it alone, and he reaches out to druids as far away as {link:feralas}Feralas{/link} for aid.]=],
		},
		{
			title = "Deeds",
			text = [=[• He keeps watch over {link:stonetalon-peak}Stonetalon Peak{/link} and the druids who dwell there.
• He sends travellers against the Bloodfury harpies, who deny the druids passage into the {link:the-charred-vale}Charred Vale{/link}.
• He seeks the aid of the druid {link:falfindel-waywarder}Falfindel Waywarder{/link} of {link:feralas}Feralas{/link}, who can call great spirits of the forest to the ruined vale.
• He receives the travellers whom the forest spirits send him from {link:ashenvale}Ashenvale{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle tells how long Albagorm has kept the peak, or what he did before the goblins came.]=],
		},
	},
	chapters = {
		{
			key = "the-travesty-of-the-vale",
			title = "The Travesty of the Vale",
			hint = "Answer the keeper's call to clear the Charred Vale.",
			unlock = {
				{ type = "quest", id = 1057 },
			},
			text = [=[Albagorm names the ruin of the {link:the-charred-vale}Charred Vale{/link} plainly: greed. The goblins' machines set the vale afire, and now the Bloodfury harpies roost in its ashes and drive off any druid who comes to plant again. Before the vale can be healed, the harpies must be driven out. He does not ask for mercy toward them.]=],
		},
		{
			key = "a-call-to-feralas",
			title = "A Call to Feralas",
			hint = "Carry the keeper's plea far to the south.",
			unlock = {
				{ type = "quest", id = 1059 },
			},
			text = [=[The harpies have been broken, but they will return. Albagorm knows that seeds alone cannot outrun them. He sends word across the whole breadth of {link:kalimdor}Kalimdor{/link} to the druid {link:falfindel-waywarder}Falfindel Waywarder{/link}, on the edge of the forests of {link:feralas}Feralas{/link}. The keeper believes that only the great spirits of the forest can reclaim the vale in time.]=],
		},
	},
	mentions = {
		{
			text = [=[Journey to {link:stonetalon-peak}Stonetalon Peak{/link}, sent by the druid {link:faldreas-goeth-shael}Faldreas{/link}]=],
			unlock = {
				{ type = "quest", id = 1056 },
			},
		},
		{
