})

Add({
	kind = "figure",
	id = "kaela-shadowspear",
	title = "Kaela Shadowspear",
	aliases = { "Kaela" },
	subtitle = "Sentinel of Stonetalon",
	tier = "B",
	region = "stonetalon-mountains",
	npc = { 4080 },
	allegiance = "Sentinels · Darnassus",
	found = "The overlook at the western edge of Windshear Crag",
	pin = { x = 59.9, y = 66.8 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Find the Sentinel who overlooks the valley entering Windshear Crag.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Kaela Shadowspear is a Sentinel of {link:ashenvale}Ashenvale{/link}, sent into {link:stonetalon-mountains}Stonetalon{/link} to learn what was happening to the land. She found the forests of {link:windshear-crag}Windshear Crag{/link} cut down and the {link:the-charred-vale}Charred Vale{/link} in flames. She has stayed ever since, fighting the goblins from an overlook above the crag. Beside her works the {link:gnomes}gnome{/link} mage {link:gaxim-rustfizzle}Gaxim Rustfizzle{/link}, a partnership that her own people find hard to believe.]=],
		},
		{
			title = "Significance",
			text = [=[Kaela is the proof of how grave matters have become. A {link:night-elves}night elf{/link} and a {link:gnomes}gnome{/link}, a Sentinel who distrusts the arcane and a mage who delights in it, have joined hands against a common enemy. Kaela asks others not to judge {link:gaxim-rustfizzle}Gaxim{/link} too quickly. That she can say so at all is a sign of the times.]=],
		},
		{
			title = "Deeds",
			text = [=[• She was sent to {link:stonetalon-mountains}Stonetalon{/link} on the order of Sentinel Wolfrunner, and her friend {link:sentinel-thenysil}Tara Thenysil{/link} in {link:astranaar}Astranaar{/link} has long waited for word of her.
• She fights the {link:venture-company}Venture Company{/link}'s destruction of the forests.
• She hunts the burning spirits loosed in the {link:the-charred-vale}Charred Vale{/link}.
• She takes shrapnel from the wounded treants of the vale, so that {link:gaxim-rustfizzle}Gaxim{/link} may learn how they were corrupted.]=],
		},
	},
	chapters = {
		{
			key = "the-weeping-vale",
			title = "The Weeping Vale",
			hint = [=[Aid the Sentinel against the burning spirits of the Charred Vale.]=],
			unlock = {
				{ type = "quest", id = 1083 },
			},
			text = [=[The first time Kaela saw the {link:the-charred-vale}Charred Vale{/link}, she nearly wept. The goblins had not only burned the trees. In their folly they had set loose elementals of flame, stone and rage, and while those spirits walk the vale, she says, the land has no chance to see the smile of Elune.]=],
		},
		{
			key = "word-to-astranaar",
			title = "Word to Astranaar",
			hint = "Bring the Sentinel's news home to Ashenvale.",
			unlock = {
				{ type = "quest", id = 1082 },
			},
			text = [=[When the goblins have been dealt a blow, Kaela sends word north at last: she and {link:gaxim-rustfizzle}Gaxim{/link} are alive, and they are well on the way to stopping the {link:venture-company}Venture Company{/link}. In {link:astranaar}Astranaar{/link}, {link:sentinel-thenysil}Tara Thenysil{/link} hears the news and is glad, and not only for Kaela. She finds herself glad for the {link:gnomes}gnome{/link} as well.]=],
		},
	},
	mentions = {
		{
			text = [=[On Guard in {link:stonetalon-mountains}Stonetalon{/link}, sent by {link:sentinel-thenysil}Sentinel Thenysil{/link}]=],
			unlock = {
				{ type = "quest", id = 1070 },
			},
		},
		{
			text = "On Guard in {link:stonetalon-mountains}Stonetalon{/link}",
			unlock = {
				{ type = "quest", id = 1085 },
			},
		},
		{
			text = "Enraged Spirits",
			unlock = {
				{ type = "quest", id = 1083 },
			},
		},
		{
			text = "Wounded Ancients",
			unlock = {
				{ type = "quest", id = 1084 },
			},
		},
		{
			text = [=[Kaela's Update, carried from {link:gaxim-rustfizzle}Gaxim{/link}]=],
			unlock = {
				{ type = "quest", id = 1091 },
			},
		},
		{
			text = "Update for {link:sentinel-thenysil}Sentinel Thenysil{/link}",
			unlock = {
				{ type = "quest", id = 1082 },
			},
		},
	},
	bonds = {
		{ id = "gaxim-rustfizzle", name = "Gaxim Rustfizzle", note = "her unlikely partner" },
		{ id = "keeper-albagorm", name = "Keeper Albagorm", note = "guards the peak above her" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "hears of her mission" },
	},
})

Add({
	kind = "figure",
	id = "gaxim-rustfizzle",
	title = "Gaxim Rustfizzle",
	aliases = { "Gaxim" },
	subtitle = "Gnome of the Enlightened Assembly",
	tier = "B",
	region = "stonetalon-mountains",
	npc = { 4077 },
	allegiance = [=[Gnomeregan Exiles · Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences]=],
	found = [=[Beside Kaela Shadowspear, at the western edge of Windshear Crag]=],
	pin = { x = 59.5, y = 67.1 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Look for the gnome who works beside the Sentinel above Windshear Crag.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Gaxim Rustfizzle is a {link:gnomes}gnome{/link} mage and tinker, and a proud member of a learned society with a very long name: the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. He came to {link:stonetalon-mountains}Stonetalon{/link} with the Sentinel {link:kaela-shadowspear}Kaela Shadowspear{/link}. He believes, with all the force of his small frame, that a blend of magic, mixtures and mechanisms can save the forests of the night elves. He intends to prove it with explosives.]=],
		},
		{
			title = "Significance",
			text = [=[Gaxim stands for an idea the {link:night-elves}kaldorei{/link} have long resisted: that magic and craft, used well, can serve the forest rather than harm it. He says openly that the night elves need magic, and that the world needs it. His war on the {link:venture-company}Venture Company{/link} is his argument.]=],
		},
		{
			title = "Deeds",
			text = [=[• He herds the goblins back with well-placed detonations along the mountains' edges.
• He devises remote explosives from a rare compound, NG-5, and a messaging spell.
• He plans two raids on the {link:venture-company}Venture Company{/link}, one for its engineering plans and one for its letters.
• He studies the shrapnel from the corrupted treants of the {link:the-charred-vale}Charred Vale{/link}.]=],
		},
	},
	chapters = {
		{
