Add({
	kind = "figure",
	id = "seereth-stonebreak",
	title = "Seereth Stonebreak",
	aliases = { "Seereth" },
	subtitle = "Shaman of the Horde",
	tier = "B",
	region = "the-barrens",
	npc = { 4049 },
	allegiance = "Horde · Orgrimmar",
	found = "Honor's Stand, on the border of the Barrens and Stonetalon",
	pin = { x = 35.3, y = 27.9 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Find the shaman who keeps camp on the western road where the Barrens climb toward Stonetalon.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Seereth Stonebreak is a young shaman of the {link:horde}Horde{/link}, sent from {link:orgrimmar}Orgrimmar{/link} to answer the cries of the {link:stonetalon-mountains}Stonetalon Mountains{/link}. The elder far seer {link:zor-lonetree}Zor Lonetree{/link} heard that the land was in pain. Seereth was the one he sent to learn why. She found the goblins of the {link:venture-company}Venture Company{/link} cutting and burning the forests, and she has made her camp on the border ever since, gathering whatever help she can.]=],
		},
		{
			title = "Significance",
			text = [=[Seereth is the {link:horde}Horde{/link}'s first answer to the plight of {link:stonetalon-mountains}Stonetalon{/link}. It was her word that carried the matter to the {link:tauren}tauren{/link} elders, and through them to {link:magatha-grimtotem}Magatha Grimtotem{/link} and the {link:forsaken}Forsaken{/link}. What began as a shaman's vision became a plot of poison.]=],
		},
		{
			title = "Deeds",
			text = [=[• She reports the great deforestation of {link:stonetalon-mountains}Stonetalon{/link} to {link:orgrimmar}Orgrimmar{/link} and asks for aid.
• She sends warriors into {link:windshear-crag}Windshear Crag{/link} against the goblins and their servants.
• She dreams of the two shredders that fell the trees of the crag.
• She seeks the counsel of the {link:tauren}tauren{/link} elders, and of {link:magatha-grimtotem}Magatha{/link} above all.]=],
		},
	},
	chapters = {
