			hint = "Answer the far seer's summons to the Stonetalon border.",
			unlock = {
				{ type = "quest", id = 1061 },
			},
			text = [=[Seereth hears the spirits of {link:stonetalon-mountains}Stonetalon{/link} as a shaman hears them, and what she hears is rage. The goblins have taken the trees, and the spirits are nearly blind with pain. She does not counsel patience. She asks that the {link:venture-company}Venture Company{/link} be shown the only language it understands.]=],
		},
		{
			key = "xt-4-and-xt-9",
			title = "XT:4 and XT:9",
			hint = "Silence the machines of Seereth's vision.",
			unlock = {
				{ type = "quest", id = 1068 },
			},
			text = [=[Most of the spirits' whispers are lost to her, but one vision came clear: two man-shaped machines in {link:windshear-crag}Windshear Crag{/link}, felling trees with impossible speed, marked with the signs XT:4 and XT:9. When both were destroyed, many of the spirits were soothed. Seereth did not rejoice. If the goblins did not leave the mountains, she warned, worse was yet to come.]=],
		},
	},
	mentions = {
