Add({
	kind = "figure",
	id = "maggran-earthbinder",
	title = "Maggran Earthbinder",
	aliases = { "Maggran" },
	subtitle = "Defender of Sun Rock",
	tier = "B",
	region = "stonetalon-mountains",
	npc = { 11860 },
	allegiance = "Horde · Thunder Bluff",
	found = "Sun Rock Retreat",
	pin = { x = 47.2, y = 61.2 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Speak with the tauren who commands the defense of Sun Rock Retreat.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Maggran Earthbinder is a {link:tauren}tauren{/link} warrior who keeps the defense of {link:sun-rock-retreat}Sun Rock Retreat{/link}. He believes that his people are the protectors of these lands, and he takes that duty to heart. He carries a scar from the fangs of the spider {link:besseleth}Besseleth{/link}, and he has made war on the Bloodfury harpies for so long that he is not sure what he will do without them.]=],
		},
		{
			title = "Significance",
			text = [=[Maggran is the hand of the {link:horde}Horde{/link} in {link:stonetalon-mountains}Stonetalon{/link}. Where the shaman heal, he fights, and the bounties he posts are the measure of every danger in the mountains.]=],
		},
		{
			title = "Deeds",
			text = [=[• He posts bounties on the Bloodfury harpies and on their queen.
• He sets a price on the head of {link:besseleth}Besseleth{/link}, the spider of {link:webwinder-path}Sishir Canyon{/link}, who once wounded him.
• He sends a reserve warrior to relieve Grish Longrunner at the {link:the-great-lift}Great Lift{/link}, so the young guard may visit his family.
• He sends the harpies' sunstones to {link:mor-rogal}Mor'rogal{/link}, who has a use for them.]=],
		},
	},
	chapters = {
		{
			key = "the-harpy-plague",
			title = "The Harpy Plague",
			hint = "Answer Maggran's call against the Bloodfury harpies.",
			unlock = {
				{ type = "quest", id = 6282 },
			},
			text = [=[Maggran does not see the Bloodfuries as a local trouble. To him they are the source of the harpies that plague all of {link:kalimdor}Kalimdor{/link}, a sickness that spreads outward from the {link:the-charred-vale}Charred Vale{/link} and traps the innocent within its bounds. Thinning their numbers is not enough. The cure, he says, is their queen.]=],
		},
		{
			key = "after-the-ripper",
			title = "After the Ripper",
			hint = "Bring down the queen of the Bloodfury harpies.",
			unlock = {
				{ type = "quest", id = 6283 },
			},
			text = [=[When the {link:bloodfury-ripper}Bloodfury Ripper{/link} was slain, the anger went out of Maggran. It surprised him. For years the evil beside his land had kept his thoughts sharp, and now they were quiet. Perhaps, he said, that was good. Perhaps now he could turn to the good, as a {link:tauren}tauren{/link} should.]=],
		},
		{
			key = "the-old-predator",
			title = "The Old Predator",
			hint = "End the menace of Sishir Canyon.",
			unlock = {
				{ type = "quest", id = 6284 },
			},
			text = [=[{link:besseleth}Besseleth{/link} is an old hunter of these hills. She once caught Maggran on the {link:webwinder-path}Webwinder Path{/link} at night, and he barely escaped her. With her gone, he hopes, more travellers will come to {link:sun-rock-retreat}Sun Rock{/link} without fear of what waits in the dark.]=],
		},
	},
	mentions = {
		{
			text = "{link:harpies}Harpies{/link} Threaten",
			unlock = {
				{ type = "quest", id = 6282 },
			},
		},
		{
			text = "Bloodfury Bloodline",
			unlock = {
				{ type = "quest", id = 6283 },
			},
