				{ type = "quest", id = 6284 },
			},
		},
		{
			text = "Calling in the Reserves",
			unlock = {
				{ type = "quest", id = 5881 },
			},
		},
		{
			text = "Bloodfury Trinkets",
			unlock = {
				{ type = "quest", id = 86576 },
			},
		},
	},
	bonds = {
		{ id = "bloodfury-ripper", name = "Bloodfury Ripper", note = "the queen he wanted dead" },
		{ id = "besseleth", name = "Besseleth", note = "left him a scar" },
		{ id = "mor-rogal", name = "Mor'rogal", note = "receives the sunstones" },
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "serves Sun Rock with him" },
	},
})

Add({
	kind = "figure",
	id = "tammra-windfield",
	title = "Tammra Windfield",
	aliases = { "Tammra" },
	subtitle = "Healer of the Land",
	tier = "B",
	region = "stonetalon-mountains",
	npc = { 11864 },
	allegiance = "Horde · Thunder Bluff",
	found = "Sun Rock Retreat",
	pin = { x = 47.5, y = 58.4 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Seek the tauren of Sun Rock who works to heal the land with the blessings of the Earthmother.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Tammra Windfield is a {link:tauren}tauren{/link} of {link:sun-rock-retreat}Sun Rock Retreat{/link} who has set herself the task of healing {link:stonetalon-mountains}Stonetalon{/link}. She believes that only the blessings of the Earthmother can cure the wounds that greed and war have left. She works with seeds, chants and patience. She is also the aunt of {link:kaya-flathoof}Kaya Flathoof{/link}, a girl {link:grimtotem-clan}the Grimtotem{/link} carried off, and whom her family believed dead.]=],
		},
		{
			title = "Significance",
			text = [=[Tammra is the other face of the {link:horde}Horde{/link} in {link:stonetalon-mountains}Stonetalon{/link}. Where the warriors of {link:sun-rock-retreat}Sun Rock{/link} cull the harpies, she plants. Her hope is that one day the {link:venture-company}Venture Company{/link} will pack up its saws, the fire spirits will calm and the land itself will push the harpies out.]=],
		},
		{
