		},
		{
			title = "Significance",
			text = [=[Mor'rogal uncovered one of the gravest threats in {link:stonetalon-mountains}Stonetalon{/link}: a sleeping earthen, a creature of the titans, buried in Resonite beneath the ravine. Had it woken at full strength, he believed, all of Stonetalon would have been lost.]=],
		},
		{
			title = "Deeds",
			text = [=[• He sends seekers into the cave of {link:boulderslide-ravine}Boulderslide Ravine{/link} to learn what the kobolds are mining.
• He recognizes the earthen magic in Resonite from an old legend.
• He enchants the Resonite to break open the cask that held the earthen {link:goggeroc}Goggeroc{/link}.
• He finds a use for the golden sunstones that the harpies hoard.]=],
		},
	},
	chapters = {
