			hint = [=[Learn what the kobolds are digging for in Boulderslide Ravine.]=],
			unlock = {
				{ type = "quest", id = 6421 },
			},
			text = [=[The ore samples came back from the cave, and Mor'rogal turned them in his hands until he remembered. Resonite bears a trace of earthen magic. The legends say that the earthen were made by the titans to shape the land itself. If the kobolds had dug deep enough to find Resonite, they had dug deep enough to find an earthen.]=],
		},
