			hint = [=[Wake the sleeper beneath the ravine before he wakes on his own.]=],
			unlock = {
				{ type = "quest", id = 6481 },
			},
			text = [=[Mor'rogal could not stop {link:goggeroc}Goggeroc{/link} from waking. He chose to wake him first, while he was weak from his long sleep. With an enchanted crystal the cask was broken, and the earthen was slain before his strength returned. Mor'rogal named it a deed that all of {link:kalimdor}Kalimdor{/link} would owe.]=],
