			text = [=[Braelyn Firehand dwells among the {link:horde}Horde{/link} at {link:sun-rock-retreat}Sun Rock Retreat{/link}, but she is no friend of the {link:tauren}tauren{/link}'s faith. She hates the druids of {link:stonetalon-peak}Stonetalon Peak{/link}, who in her words stifle the flow of magic across the mountains. She was sent here by a master who waits in {link:jaedenar}Jaedenar{/link}, far to the north, and she may not return until her work is done. She speaks of the age of {link:azshara}Azshara{/link} as if she remembers it.]=],
		},
		{
			title = "Significance",
			text = [=[Braelyn is a thread of something old and dark in {link:stonetalon-mountains}Stonetalon{/link}. She calls the ruined temple on the peak "our" temple of {link:azshara}Azshara{/link}. She knew {link:keeper-ordanus}Ordanus{/link}, a son of {link:cenarius}Cenarius{/link}, long ago, and she says he held himself above even the Highborne. Whatever she is, she hungers for magic as others hunger for bread.]=],
		},
		{
			title = "Deeds",
			text = [=[• She seeks the death of the Cenarion druids and the children of {link:cenarius}Cenarius{/link} on the peak.
• She hunts {link:keeper-ordanus}Ordanus{/link}, whom the druids spirited away to {link:ashenvale}Ashenvale{/link}.
• She wrests the secrets of the {link:the-talon-den}Talon Den{/link} from a captured druid.]=],
		},
		{
			title = "Unrecorded",
