			unlock = {
				{ type = "quest", id = 1087 },
			},
			text = [=[In {link:stonetalon-mountains}Stonetalon{/link}, Braelyn says, drawing on magic is like drawing water with a bucket full of holes. When the druids and the children of {link:cenarius}Cenarius{/link} fell, she felt the flow return, sweet and rushing. The {link:night-elves}kaldorei{/link}, she says, are fools to spurn it.]=],
		},
		{
