			hint = "Find the son of Cenarius whom the druids hid from her.",
			unlock = {
				{ type = "quest", id = 1088 },
			},
			text = [=[With her sight Braelyn found him: {link:keeper-ordanus}Ordanus{/link}, one of the eldest sons of the forest god, hidden at the top of a great tree at {link:raynewood-retreat}Raynewood{/link} in {link:ashenvale}Ashenvale{/link}. The druids had taken him from the peak before she could reach him. When his head was brought to her, she looked on it without pity. His head, she said, no longer rose so high.]=],
